INSERT INTO `activities_attachments` (`id`, `entityType`, `entityId`, `fileName`, `fileSize`, `mimeType`, `fileUrl`, `fileKey`, `activityType`, `isEmailAttachment`, `emailSubject`, `emailDate`, `emailDirection`, `uploadedBy`, `createdAt`) VALUES (1, 'customer', 2, 'test_email.pdf', 1411, 'application/pdf', 'https://d2xsxph8kpxj0f.cloudfront.net/310419663031934298/bQwuvX7ycRD88MLXJHLZXd/attachments/customer/2/1763520681971-fovdo-test_email.pdf', 'attachments/customer/2/1763520681971-fovdo-test_email.pdf', 'email', 1, NULL, NULL, NULL, 1, '2025-11-19 02:51:22');
INSERT INTO `ai_agent_communications` (`id`, `conversationId`, `senderAgentId`, `receiverAgentId`, `messageType`, `content`, `context`, `reasoning`, `confidence`, `createdAt`) VALUES (1, 'cross-disc-a0399f35-519d-4549-8ef5-1796dd55f93a', 1, NULL, 'broadcast', 'Team, we''re launching an AI-Powered Customer Analytics Platform. I need each department to provide their analysis and requirements. Target launch: Q2 2025. Budget: $500K.', '{"budget":500000,"project":"AI Customer Analytics Platform","timeline":"Q2 2025"}', 'Strategic initiative to enhance customer insights and drive data-driven decision making', 95, '2025-11-21 08:13:02');
INSERT INTO `ai_agent_communications` (`id`, `conversationId`, `senderAgentId`, `receiverAgentId`, `messageType`, `content`, `context`, `reasoning`, `confidence`, `createdAt`) VALUES (2, 'cross-disc-a0399f35-519d-4549-8ef5-1796dd55f93a', 2, NULL, 'internal_thought', 'Need to assess: development costs, infrastructure, team salaries, marketing budget, contingency. Must ensure positive ROI within 18 months.', NULL, 'Financial viability analysis before commitment', 90, '2025-11-21 08:13:02');
INSERT INTO `ai_agent_communications` (`id`, `conversationId`, `senderAgentId`, `receiverAgentId`, `messageType`, `content`, `context`, `reasoning`, `confidence`, `createdAt`) VALUES (3, 'cross-disc-a0399f35-519d-4549-8ef5-1796dd55f93a', 3, NULL, 'internal_thought', 'Target market: Enterprise B2B (500+ employees). Key differentiators: AI-powered insights, real-time analytics, predictive modeling. Need strong content marketing and thought leadership.', NULL, 'Market positioning analysis for competitive advantage', 92, '2025-11-21 08:13:02');
INSERT INTO `ai_agent_communications` (`id`, `conversationId`, `senderAgentId`, `receiverAgentId`, `messageType`, `content`, `context`, `reasoning`, `confidence`, `createdAt`) VALUES (4, 'cross-disc-a0399f35-519d-4549-8ef5-1796dd55f93a', 4, NULL, 'internal_thought', 'Architecture requirements: Scalable microservices, real-time data processing, ML pipeline for predictive analytics, SOC 2 compliance. Stack: Node.js, Python (ML), PostgreSQL, Redis, Kubernetes.', NULL, 'Technical feasibility and scalability assessment', 93, '2025-11-21 08:13:02');
INSERT INTO `ai_agent_communications` (`id`, `conversationId`, `senderAgentId`, `receiverAgentId`, `messageType`, `content`, `context`, `reasoning`, `confidence`, `createdAt`) VALUES (5, 'cross-disc-a0399f35-519d-4549-8ef5-1796dd55f93a', 6, NULL, 'internal_thought', 'Hiring needs: 5 engineers (2 backend, 2 ML, 1 DevOps), 2 marketers (1 content, 1 demand gen), 1 product manager. Timeline: 3 months. Competitive market requires strong employer branding.', NULL, 'Talent acquisition strategy aligned with technical and marketing requirements', 87, '2025-11-21 08:13:02');
INSERT INTO `ai_agent_communications` (`id`, `conversationId`, `senderAgentId`, `receiverAgentId`, `messageType`, `content`, `context`, `reasoning`, `confidence`, `createdAt`) VALUES (6, 'cross-disc-a0399f35-519d-4549-8ef5-1796dd55f93a', 1, NULL, 'internal_thought', 'All departments aligned. CFO confirms financial viability (180% ROI), CMO has strong GTM strategy, CTO architecture is solid, CHRO can hire team in 3 months. Green light for launch.', NULL, 'Cross-functional alignment achieved, all key risks mitigated', 94, '2025-11-21 08:13:02');
INSERT INTO `ai_agent_communications` (`id`, `conversationId`, `senderAgentId`, `receiverAgentId`, `messageType`, `content`, `context`, `reasoning`, `confidence`, `createdAt`) VALUES (7, 'cross-disc-a0399f35-519d-4549-8ef5-1796dd55f93a', 1, NULL, 'decision', 'DECISION: Approved. Launch AI-Powered Customer Analytics Platform. Budget: $500K initial + $980K annual team cost. Timeline: Q2 2025 launch. CFO proceed with budget allocation, CMO execute GTM strategy, CTO begin architecture implementation, CHRO start hiring immediately.', '{"annualCost":980000,"decision":"APPROVED","initialBudget":500000,"launchDate":"Q2 2025","nextSteps":["CFO: Allocate budget","CMO: Execute GTM strategy","CTO: Implement architecture","CHRO: Begin hiring"]}', 'Strong cross-functional consensus, clear ROI, manageable risks, strategic fit', 96, '2025-11-21 08:13:02');
